svg.script:
(function () {
  var svg = document.documentElement;
  if (!svg || svg.tagName.toLowerCase() !== 'svg') { return; }

  var STEPS = {
    A: { name: 'A. A guarded tool call', steps: [
      'The model calls a shell or file tool.',
      'Claude Code fires PreToolUse before the call runs.',
      "The hook runner matches the event in io-guard's hooks.json.",
      "The mcp_tool hook names the plugin's own server, plugin:io-guard:io.",
      'The MCP client calls hook.pre_tool_use on the io server, which is already running.',
      'The protocol layer dispatches the call by name.',
      'The registry hands it to the hook bridge tool.',
      'The bridge rebuilds the Event from the substituted fields.',
      "hooks.entry runs the pipeline in this session's Context.",
      'The pipeline selects the checks for this event, orders them and runs them, within 300 ms, or 2 s at most.',
      'Checks call lib: values in, values out. Each code a check gives is also one telemetry line.',
      'Checks read the config, the probe, git and the session state from the Context, and the end of the transcript, for a call Claude Code refused before any hook ran.',
      "The answer returns as the tool result, and Claude Code reads it as the hook's decision: deny, ask or allow with a rewritten command, a fixed Write or Edit input that leaves the decision to Claude Code, or context only.",
      'The permission rules and the auto-mode classifier judge the rewritten input.',
      'The approved command runs.',
      'A moved command body waits in the scratchpad as a file.',
      'A refusal names its code and its fix, and the skill tells the model which tool to call instead.'
    ] },
    B: { name: 'B. An io tool call', steps: [
      'The model calls an io tool, after ToolSearch loads it. An io.run call first meets the user\'s Bash and PowerShell rules at its PreToolUse hook.',
      'The MCP client sends tools/call to the io server.',
      'The protocol layer checks the era and dispatches by name.',
      'The registry hands the typed input to the tool.',
      'The tool calls lib: the profile, the anchors, the file lock and the atomic write. Each call is one telemetry line.',
      'A background run or a snapshot gets a handle, and a decision goes to the user.',
      'lib replaces the file atomically, under a lock that other sessions share.',
      'lib reads git for hunks, and io.stage writes the index.'
    ] },
    C: { name: 'C. Session start and the heartbeat', steps: [
      'SessionStart, and each new prompt, run the two command hooks through pyrun.',
      'hook.py probes the platform, or checks the heartbeat, through lib.',
      "The server's watchdog writes the heartbeat every 5 seconds.",
      'lib writes the probe and the heartbeat into io-guard\'s folder. A heartbeat older than 30 seconds, or a server Claude Code skipped after a failed start, gives one warning.'
    ] },
    D: { name: 'D. Telemetry and the dashboard', steps: [
      'Every code a check gives is one telemetry line, with no file content.',
      'Every io tool call is one telemetry line.',
      'lib appends them to one file per session. Each server start deletes the files past telemetry.retention_days, 90 by default.',
      'The dashboard and report.py show the counts by day and code, the percentiles, and each code\'s last lines.'
    ] }
  };

  var arrows = Array.prototype.slice.call(svg.querySelectorAll('.arrow'));
  var badges = Array.prototype.slice.call(svg.querySelectorAll('.badge'));
  var boxes = Array.prototype.slice.call(svg.querySelectorAll('.box'));
  var buttons = Array.prototype.slice.call(svg.querySelectorAll('.btn[data-flow]'));
  var side = document.getElementById('side-body');
  var sideFrame = document.getElementById('side');
  var staticPanels = Array.prototype.slice.call(svg.querySelectorAll('.static-panel'));
  var current = 'all';
  var timer = null;

  function showSide(visible) {
    sideFrame.style.display = visible ? 'block' : 'none';
    staticPanels.forEach(function (p) { p.style.display = visible ? 'none' : 'inline'; });
  }

  function arrowsOf(flow) {
    return arrows.filter(function (a) { return a.getAttribute('data-flows').split(' ').indexOf(flow) >= 0; });
  }
  function stepArrow(flow, index) {
    var badge = badges.filter(function (b) { return b.getAttribute('data-flow') === flow && +b.getAttribute('data-step') === index + 1; })[0];
    if (!badge) { return null; }
    var cx = +badge.querySelector('circle').getAttribute('cx');
    var cy = +badge.querySelector('circle').getAttribute('cy');
    var best = null, bestDist = 1e9;
    arrowsOf(flow).forEach(function (a) {
      var len = a.getTotalLength();
      for (var t = 0; t <= len; t += 4) {
        var p = a.getPointAtLength(t);
        var d = (p.x - cx) * (p.x - cx) + (p.y - cy) * (p.y - cy);
        if (d < bestDist) { bestDist = d; best = a; }
      }
    });
    return best;
  }
  function escapeHtml(text) {
    return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  }
  function renderSteps(flow, active) {
    var data = STEPS[flow];
    var html = '<div style="font-weight:700;font-size:13.5px;margin-bottom:8px">' + escapeHtml(data.name) + '</div><ol style="margin:0;padding-left:26px">';
    data.steps.forEach(function (s, i) {
      var on = i === active;
      html += '<li style="margin:0 0 6px 0;' + (on ? 'font-weight:700' : '') + '">' + escapeHtml(s) + '</li>';
    });
    side.innerHTML = html + '</ol>';
  }
  function renderBox(box) {
    var title = box.querySelector('.t').textContent;
    var text = box.querySelector('title').textContent;
    side.innerHTML = '<div style="font-weight:700;font-size:13.5px;margin-bottom:8px">' + escapeHtml(title) + '</div><div>' + escapeHtml(text) + '</div>';
  }
  function select(flow) {
    stop();
    current = flow;
    buttons.forEach(function (b) { b.classList.toggle('on', b.getAttribute('data-flow') === flow); });
    var inFlow = flow === 'all' ? null : arrowsOf(flow);
    var boxIds = {};
    if (inFlow) { inFlow.forEach(function (a) { boxIds[a.getAttribute('data-from')] = 1; boxIds[a.getAttribute('data-to')] = 1; }); }
    arrows.forEach(function (a) {
      a.classList.remove('active');
      a.classList.toggle('dim', !!inFlow && inFlow.indexOf(a) < 0);
      if (inFlow && inFlow.indexOf(a) >= 0) { a.setAttribute('class', a.getAttribute('class').replace(/\bf[abcd]\b/g, '') .trim() + ' f' + flow.toLowerCase()); }
      else { a.setAttribute('class', a.getAttribute('class').replace(/\bf[abcd]\b/g, '').trim() + ' f' + a.getAttribute('data-flows').split(' ')[0].toLowerCase()); }
    });
    badges.forEach(function (b) { b.classList.toggle('dim', !!inFlow && b.getAttribute('data-flow') !== flow); });
    boxes.forEach(function (b) { b.classList.toggle('dim', !!inFlow && !boxIds[b.id]); b.classList.remove('hl'); });
    if (inFlow) { renderSteps(flow, -1); showSide(true); }
    else { showSide(false); }
  }
  function stop() {
    if (timer) { clearInterval(timer); timer = null; }
    arrows.forEach(function (a) { a.classList.remove('active'); });
  }
  function play() {
    var flow = current === 'all' ? 'A' : current;
    if (current !== flow) { select(flow); }
    stop();
    var i = 0, n = STEPS[flow].steps.length;
    function tick() {
      arrows.forEach(function (a) { a.classList.remove('active'); });
      var a = stepArrow(flow, i);
      if (a) { a.classList.add('active'); }
      renderSteps(flow, i);
      i = (i + 1) % n;
    }
    tick();
    timer = setInterval(tick, 1600);
  }

  buttons.forEach(function (b) {
    b.addEventListener('click', function () { select(b.getAttribute('data-flow')); });
    b.addEventListener('keydown', function (e) { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); select(b.getAttribute('data-flow')); } });
  });
  var playButton = svg.querySelector('#play');
  playButton.addEventListener('click', play);
  playButton.addEventListener('keydown', function (e) { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); play(); } });

  boxes.forEach(function (box) {
    function show() {
      boxes.forEach(function (b) { b.classList.remove('hl'); });
      box.classList.add('hl');
      showSide(true);
      renderBox(box);
    }
    function hide() {
      box.classList.remove('hl');
      if (current === 'all') { showSide(false); }
      else if (!timer) { renderSteps(current, -1); }
    }
    box.addEventListener('mouseenter', show);
    box.addEventListener('focus', show);
    box.addEventListener('mouseleave', hide);
    box.addEventListener('blur', hide);
  });

  showSide(false);
})();
